// Categories NOT in the default "ALL" deck — they only appear when picked.
export const OPT_IN = ['couples', 'spicy'];
export const CORE = CATS.filter((c) => !OPT_IN.includes(c.id)).map((c) => c.id);

export const CATEGORIES = CATS;
export const QUESTIONS = Q;
export const SURFACE_OPTIONS = SURFACES;
export const TINTS = CAT_TINT;
export const STRINGS = UI;

// O(1) lookup from a question's stableId (row[1]) back to its row — used
// anywhere a question is addressed by id instead of array position (API
// routes, analytics, share/favorite state) so array reordering never
// invalidates a reference.
export const QUESTION_BY_ID = new Map(Q.map((row) => [row[1], row]));
